using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEditor;using Mewgic.Daily;using Mewgic.Rewards;
namespace Mewgic {
public sealed class HomeEventsAuditProbe:MonoBehaviour {
 List<object> screens=new List<object>();List<string> errors=new List<string>(),checks=new List<string>();string folder,save;bool had;
 static HomeEventsAuditProbe active;
 void Awake(){if(active!=null){Destroy(gameObject);return;}active=this;DontDestroyOnLoad(gameObject);folder="docs/Part09E/"+SessionState.GetString("Part09E.Phase","Before")+"/";Directory.CreateDirectory(folder);had=PlayerPrefs.HasKey(GameplayProgress.StorageKey);save=PlayerPrefs.GetString(GameplayProgress.StorageKey,"");GameplayProgress.UseTestProfile();Application.logMessageReceived+=Log;}
 void Log(string m,string stack,LogType t){if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors.Add(m);}
 IEnumerator Start(){var run=Run();string error=null;while(true){bool more=false;object next=null;try{more=run.MoveNext();if(more)next=run.Current;}catch(Exception e){error=e.ToString();}if(!more||error!=null)break;yield return next;}Application.logMessageReceived-=Log;bool intact=had==PlayerPrefs.HasKey(GameplayProgress.StorageKey)&&save==PlayerPrefs.GetString(GameplayProgress.StorageKey,"");GameplayProgress.RestorePlayerProfile();GameplayLevelCatalog.ResetSelection();File.WriteAllText("docs/Part09E/UI_AUDIT.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{success=error==null&&errors.Count==0&&intact,error,errors,checks,screens,playerSaveIntact=intact},Newtonsoft.Json.Formatting.Indented));File.Copy("docs/Part09E/UI_AUDIT.json",folder+"UI_AUDIT.json",true);EditorApplication.isPlaying=false;}
 void Tap(string name){var g=GameObject.Find(name);if(g==null)throw new Exception("Buton bulunamadı: "+name);g.GetComponent<Button>().onClick.Invoke();checks.Add("Buton çalıştı: "+name);}
 void Shot(string name){foreach(int h in new[]{1600,1950,2000})Capture(folder+name+"-"+h+".png",900,h,h==2000);}
 IEnumerator Run(){yield return null;yield return null;yield return null;
 Check(GameObject.Find("EventsButton")==null&&GameObject.Find("EventIcon")==null,"Yan Events butonu ve ikonu kaldırıldı");Tap("NavEvents");Check(FindFirstObjectByType<RewardHubPanel>().IsOpen,"Alt Events gerçek merkezi açtı");Tap("RewardHubClose");Check(!FindFirstObjectByType<RewardHubPanel>().IsOpen,"Events→Home dönüşü geçti");Shot("Home");var top=FindFirstObjectByType<HomeTopBar>();Tap("SettingsButton");Shot("Settings");top.Close();top.Show("Envanter sistemi henüz geliştirilmedi. Bu sekme yalnızca önizleme bilgi panelidir.");Shot("Information");top.Close();
 var daily=FindFirstObjectByType<DailyActivitiesPanel>();daily.Open(false);Shot("DailyMissions");var task=GameObject.Find("DailyTask_0/TaskTitle").GetComponent<Text>();string originalTitle=task.text;task.text="Kazandığın bölümlerde aynı renkteki toplam dört sihirli şişeyi tamamla";Shot("DailyLongDescription");task.text=originalTitle;daily.Open(true);Shot("DailyGift");daily.Close();daily.Open(false);Tap("DailyAction_0");float dailyLimit=Time.realtimeSinceStartup+15;while(SceneManager.GetActiveScene().name!="Gameplay"){if(Time.realtimeSinceStartup>dailyLimit)throw new Exception("GİT geçişi zaman aşımı");yield return null;}yield return null;yield return null;Tap("Home");yield return null;yield return null;checks.Add("Günlük GİT→Gameplay→Home geçti");
 var hub=FindFirstObjectByType<RewardHubPanel>();for(int i=0;i<4;i++){hub.Open(i);Shot(new[]{"HubDaily","WeeklyEvents","SeasonPass","Collection"}[i]);}Tap("CollectionView_0");Shot("CollectionInfo");Tap("RewardInfoClose");Tap("PremiumInfo");Shot("PremiumInfo");Tap("RewardInfoClose");hub.Close();
 Tap("Play");float until=Time.realtimeSinceStartup+15;while(SceneManager.GetActiveScene().name!="Gameplay"){if(Time.realtimeSinceStartup>until)throw new Exception("Gameplay zaman aşımı");yield return null;}yield return null;yield return null;Shot("Gameplay");Tap("Pause");Shot("Pause");Tap("Resume");foreach(var move in Mewgic.Core.PuzzleSolver.Solve(GameplayLevelCatalog.Load(1).Bottles).Moves){Tap("Bottle "+(move.Source+1));Tap("Bottle "+(move.Target+1));yield return new WaitForSecondsRealtime(1.1f);}var end=FindFirstObjectByType<GameplayEndScreen>();if(!end.IsShowing)throw new Exception("Gerçek zafer ekranı açılmadı");Shot("Victory");Tap("ResultHome");yield return null;yield return null;checks.Add("PLAY→Gameplay→Home geçti");
 Tap("NavMap");yield return null;yield return null;var map=FindFirstObjectByType<Mewgic.Map.MapWorld>();if(map==null)throw new Exception("LevelMap açılamadı");for(int i=0;i<4;i++){map.FocusRegion(i,false);Shot("LevelMap-"+i);}map.ShowInformation(map.Points.First(p=>p.kind==Mewgic.Map.MapPointKind.LevelSlot&&p.slotIndex>1));Shot("MapInfo");Tap("MapInfoClose");map.ShowInformation(map.Points.First(p=>p.kind==Mewgic.Map.MapPointKind.Chest));Shot("MapChestInfo");
 }
 void Measure(string filename){var rows=new List<object>();foreach(var t in FindObjectsByType<Text>(FindObjectsSortMode.None)){if(!t.isActiveAndEnabled||string.IsNullOrEmpty(t.text))continue;var r=t.rectTransform;var settings=t.GetGenerationSettings(r.rect.size);int used=t.resizeTextForBestFit?t.cachedTextGenerator.fontSizeUsedForBestFit:t.fontSize;if(t.resizeTextForBestFit)used=Mathf.Clamp(Mathf.RoundToInt(used/t.pixelsPerUnit),t.resizeTextMinSize,t.resizeTextMaxSize);if(used<=0)used=t.fontSize;settings.resizeTextForBestFit=false;settings.fontSize=used;float preferred=t.cachedTextGeneratorForLayout.GetPreferredHeight(t.text,settings)/t.pixelsPerUnit;var v=new Vector3[4];r.GetWorldCorners(v);rows.Add(new{path=PathOf(t.transform),text=t.text,width=r.rect.width,height=r.rect.height,font=t.font.name,fontSize=used,preferredHeight=preferred,overflowsHeight=preferred>r.rect.height+2,alignment=t.alignment.ToString(),corners=v.Select(c=>new{x=c.x,y=c.y}).ToArray()});}screens.Add(new{capture=filename,texts=rows});}
 string PathOf(Transform t){return t.parent==null?t.name:PathOf(t.parent)+"/"+t.name;}
 Rect Bounds(RectTransform r,RectTransform relative){var corners=new Vector3[4];r.GetWorldCorners(corners);Vector2 min=Vector2.one*float.MaxValue,max=-min;foreach(var c in corners){Vector2 v=relative.InverseTransformPoint(c);min=Vector2.Min(min,v);max=Vector2.Max(max,v);}return Rect.MinMaxRect(min.x,min.y,max.x,max.y);}
 void Check(bool ok,string label){if(!ok)throw new Exception(label);checks.Add(label);}
 void Validate(RectTransform safe,string filename){if(SessionState.GetString("Part09E.Phase","")!="After")return;
 if(safe!=null)foreach(var b in FindObjectsByType<Button>(FindObjectsSortMode.None)){if(!b.isActiveAndEnabled||b.GetComponentInParent<ScrollRect>()!=null)continue;var r=Bounds((RectTransform)b.transform,safe);Check(r.xMin>=safe.rect.xMin-1&&r.xMax<=safe.rect.xMax+1&&r.yMin>=safe.rect.yMin-1&&r.yMax<=safe.rect.yMax+1,"Safe Area: "+filename+" / "+b.name);}
 var daily=FindFirstObjectByType<DailyActivitiesPanel>();if(daily==null||!daily.IsOpen||daily.GiftVisible)return;
 for(int i=0;i<4;i++){var row=(RectTransform)GameObject.Find("DailyTask_"+i).transform;var title=Bounds((RectTransform)row.Find("TaskTitle"),row);var track=Bounds((RectTransform)row.Find("ProgressTrack"),row);var icon=Bounds((RectTransform)row.Find("MissionIcon"),row);var reward=Bounds((RectTransform)row.Find("RewardIcon"),row);var amount=Bounds((RectTransform)row.Find("RewardAmount"),row);var action=Bounds((RectTransform)row.Find("DailyAction_"+i),row);
 Check(title.yMax<=row.rect.yMax-row.rect.height*.15f&&title.yMin>track.yMax,"Görev açıklaması çerçeveden ve çubuktan ayrı: "+filename+i);
 Check(icon.xMax<title.xMin&&title.xMax<reward.xMin&&reward.xMax<action.xMin,"Görev sütunları çakışmıyor: "+filename+i);
 Check(Mathf.Abs(icon.center.y-row.rect.center.y)<1&&Mathf.Abs(action.center.y-row.rect.center.y)<1,"Farklı ikon ve GİT aynı merkezde: "+filename+i);
 Check(amount.yMin>=row.rect.yMin+row.rect.height*.1f,"Ödül miktarı alt çerçeveden içeride: "+filename+i);
 }}
        void Capture(string filename,int width,int height,bool inset=false)
        {
            var canvas=FindFirstObjectByType<Canvas>();var camera=Camera.main;var p=FindFirstObjectByType<HomeCharacterPresenter>();var safe=p!=null?(RectTransform)p.transform.Find("UI"):(GameObject.Find("Safe area")??GameObject.Find("MapSafeArea"))?.GetComponent<RectTransform>();
            var mode=canvas.renderMode;var oldCam=canvas.worldCamera;float distance=canvas.planeDistance;var oldTarget=camera.targetTexture;var oldActive=RenderTexture.active;Vector2 min=safe!=null?safe.anchorMin:Vector2.zero,max=safe!=null?safe.anchorMax:Vector2.one;
            var rt=new RenderTexture(width,height,24);var tex=new Texture2D(width,height,TextureFormat.RGB24,false);
            try{
                camera.targetTexture=rt;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;if(inset&&safe!=null){safe.anchorMin=new Vector2(.035f,.04f);safe.anchorMax=new Vector2(.965f,.955f);}
                Canvas.ForceUpdateCanvases();var gameplay=FindFirstObjectByType<GameplayPresentation>();if(gameplay!=null)gameplay.Layout();var pause=GameObject.Find("PauseSafeArea");if(pause!=null&&safe!=null){var pr=(RectTransform)pause.transform;pr.anchorMin=safe.anchorMin;pr.anchorMax=safe.anchorMax;}if(p!=null){p.Layout();p.GetComponent<HomeEnvironment>().Layout();p.GetComponent<HomePotionDisplay>().Layout();}var map=FindFirstObjectByType<Mewgic.Map.MapWorld>();if(map!=null)map.Layout();var daily=FindFirstObjectByType<Mewgic.Daily.DailyActivitiesPanel>();if(daily!=null&&daily.IsOpen)daily.Layout();var hub=FindFirstObjectByType<Mewgic.Rewards.RewardHubPanel>();if(hub!=null&&hub.IsOpen)hub.Layout();Canvas.ForceUpdateCanvases();
                camera.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,width,height),0,0);tex.Apply();Validate(safe,filename);Measure(filename);File.WriteAllBytes(filename,tex.EncodeToPNG());
            }finally{camera.targetTexture=oldTarget;canvas.renderMode=mode;canvas.worldCamera=oldCam;canvas.planeDistance=distance;if(safe!=null){safe.anchorMin=min;safe.anchorMax=max;}RenderTexture.active=oldActive;DestroyImmediate(tex);rt.Release();DestroyImmediate(rt);Canvas.ForceUpdateCanvases();if(p!=null){p.Layout();p.GetComponent<HomeEnvironment>().Layout();p.GetComponent<HomePotionDisplay>().Layout();}}
        }
}
}
